import heapq

def solution(input_str):
    """
    Solves the skill improvement problem by computing the maximum possible
    skill product through optimal selection and ordering of improvements.
    """
    lines = input_str.strip().split('\n')
    k, n, m = map(int, lines[0].split())
    skills = list(map(int, lines[1].split()))

    improvements = []
    for i in range(n):
        parts = list(map(int, lines[2 + i].split()))
        improvements.append({
            'id': i + 1,
            'type': parts[0],
            'skill_idx': parts[1] - 1,
            'value': parts[2]
        })

    # Calculate the best possible improvement gain for each improvement
    def calculate_improvement_gain(skill_value, imp):
        if imp['type'] == 1:
            return abs(skill_value - imp['value'])
        elif imp['type'] == 2:
            return imp['value']
        elif imp['type'] == 3:
            return skill_value * (imp['value'] - 1) if imp['value'] > 1 else skill_value ** imp['value'] - skill_value
        return 0

    # Score each improvement based on potential gain
    scored_improvements = []
    for imp in improvements:
        gain = calculate_improvement_gain(sum(skills), imp)
        if gain > 0 and m > 0:
            scored_improvements.append((gain, imp))

    if not scored_improvements or m == 0:
        return "0\n"

    # Sort by gain (descending)
    scored_improvements.sort(key=lambda x: x[0], reverse=True)

    # Select top m improvements
    selected = [imp[1] for imp in scored_improvements[:min(len(scored_improvements), m)]]

    # For ordering: apply type 1 first (assignment sets base), then type 3 (multiply), then type 2 (add)
    # Actually, for multiplication within same skill, order matters less than assignment
    # Best order: assignment first, then multiplication, then addition

    improvement_ids = [imp['id'] for imp in selected]

    # Group by skill index
    by_skill = {}
    for imp in selected:
        if imp['skill_idx'] not in by_skill:
            by_skill[imp['skill_idx']] = []
        by_skill[imp['skill_idx']].append(imp)

    # Order improvements: for each skill, do type 1 first, then type 3, then type 2
    # Then order by which skill gives most benefit first
    def get_imp_order(imp):
        if imp['type'] == 1:
            return (0, 0, imp['skill_idx'])
        elif imp['type'] == 3:
            return (1, 0, imp['skill_idx'])
        elif imp['type'] == 2:
            return (2, 0, imp['skill_idx'])
        return (3, 0, imp['skill_idx'])

    selected_sorted = sorted(selected, key=get_imp_order)
    ordered_ids = [imp['id'] for imp in selected_sorted]

    l = len(ordered_ids)
    result = f"{l}\n"
    if l > 0:
        result += " ".join(map(str, ordered_ids))

    return result + " "
