The problem can be solved with a simpler greedy approach. For each element, if we can extend a range, we do. We need to find the minimum number of range operations plus individual deletions.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 0:
        return "0"

    i = 0
    ans = 0
    while i < n:
        if a[i] == 0:
            ans += 1
            i += 1
        else:
            j = i
            while j < n and a[j] > 0:
                j += 1

            # Find minimum in this contiguous block
            mn = min(a[i:j])
            res = mn

            # Number of breaks needed
            breaks = 0
            for k in range(i + 1, j):
                if a[k - 1] == 0:
                    breaks += 1

            ans += res + breaks
            for k in range(i, j):
                a[k] = 0
            i = j

    return str(ans)
