            val_assignments = {}
            constraints = []  # (node, coefficient, constant)

            # Set up the system using first node as reference
            ref_node = comp_nodes[0]
            ref_val = 0.0

            # Assign all nodes relative to ref
            order = comp_nodes
            visited_temp = set()
            if ref_node not in visited_temp:
                visited_temp.add(ref_node)

            stack = [ref_node]
            node_order = []

            while stack:
                u = stack.pop()
                if u in visited_temp:
                    continue
                visited_temp.add(u)
                node_order.append(u)

                # Try to find value based on ref
                for v, color in adj[u]:
                    if v == ref_node and u not in val_assignments and ref_node in val_assignments:
                        # Cycle back to ref
                        if color == 1:
                            val_assignments[u] = 1.0 - val_assignments[ref_node]
                        elif color == 2:
                            val_assignments[u] = 2.0 - val_assignments[ref_node]
                        break
                    elif v not in visited_temp and v in val_assignments:
                        if color == 1:
                            val_assignments[u] = 1.0 - val_assignments[v]
                        elif color == 2:
                            val_assignments[u] = 2.0 - val_assignments[v]

                if u not in val_assignments:
