import os
import sys

def solution(input_text):
    # Read the three strings from input
    lines = input_text.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    # Handle edge cases
    if not s1 or not s2 or not virus:
        return "0"

    # KMP preprocessing for virus
    m = len(virus)
    if m == 0:
        # Empty virus can't be a substring of non-empty LCS
        return "0"

    # Compute prefix function (pi array) for virus
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Create transition function for KMP automaton
    # trans[state][char] = next state after adding char, or state if no match
    trans = [[0] * 26 for _ in range(m + 1)]
    for state in range(m):
        for c_code in range(26):
            c = chr(ord('A') + c_code)
            if state < m and state == m:
                # Already matched full virus, invalid
                break
            if state == 1 and c == virus[state-1]:
                trans[state][c_code] = 1
            else:
                # Follow pi array
                j = state
                while j > 0:
                    if j == m:
                        j = pi[j-1]
                    if c == virus[j]:
