import collections

def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return "0"

    n, m = map(int, lines[0].split())
    events = lines[1:]

    # Divide events into segments (between type 1 events)
    segments = []
    current_segment = set()

    for event in events:
        parts = event.strip().split()
        if parts[0] == '1':
            segments.append(current_segment)
            current_segment = set()
        else:
            current_segment.add(parts[1])
    segments.append(current_segment)

    # Collect all unique friends
    all_friends = set()
    for seg in segments:
        all_friends.update(seg)

    friend_to_idx = {f: i for i, f in enumerate(sorted(all_friends))}
    m = len(friend_to_idx)

    # Build conflict graph: friends in same segment conflict
    conflict = [[False] * m for _ in range(m)]

    for seg_idx, seg in enumerate(segments):
        seg_friends = [f for f in seg if f in friend_to_idx]
        for i in range(len(seg_friends)):
            for j in range(i + 1, len(seg_friends)):
                u, v = friend_to_idx[seg_friends[i]], friend_to_idx[seg_friends[j]]
                conflict[u][v] = conflict[v][u] = True

    # Maximum Independent Set using backtracking with pruning
    best = 0

    def solve(mask, count):
        nonlocal best

        # Pruning: if we can't beat best, return
        remaining = m - bin(mask.count('1')) - 1
        if count + remaining <= best:
            return

        if mask == (1 << m) - 1:
            best = max(best, count)
            return

        # Find first uncovered vertex
        i = mask.bit_length()
        if i >= m:
            i = 0

        # Try including i if no conflicts
        included = False
        while i < m and mask & (1 << i):
            i += 1

        if i < m:
            conflicts = 0
            for j in range(i):
                if mask & (1 << j) and conflict[i][j]:
                    conflicts = 1
                    break

            if not conflicts:
                solve(mask | (1 << i), count + 1)

        # Try excluding i
        solve(mask, count)

    solve(0, 0)
    return str(best)
