def compute_fibonacci(n):
    """Compute the (n-1)th Fibonacci number where f[1]=1, f[2]=1, f[3]=2, etc."""
    if n <= 1:
        return 0
    if n == 2:
        return 1
    a, b = 1, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b

def binary_exp_matrix(matrix, n, mod):
    """Matrix exponentiation for computing Fibonacci numbers"""
    result = [[1, 0], [0, 1]]
    base = [row[:] for row in matrix]
    while n > 0:
        if n % 2 == 1:
            result = [[sum(result[i][k] * base[j][k] for k in range(2)) % mod for j in range(2)] for i in range(2)]
        base = [[sum(base[i][k] * base[j][k] for k in range(2)) % mod for j in range(2)] for i in range(2)]
        n //= 2
    return result

def fib_index(n, mod):
    """Compute the (n-1)th Fibonacci number using matrix exponentiation"""
    if n <= 1:
        return 0
    if n == 2:
        return 1
    # [f(n), f(n-1)] = M^(n-2) * [f(2), f(1)] where M = [[1,1],[1,0]]
    matrix = [[1, 1], [1, 0]]
    result = binary_exp_matrix(matrix, n - 2, mod)
    # f(n) = result[0][0] * f(2) + result[0][1] * f(1) = result[0][0] * 1 + result[0][1] * 1
    return (result[0][0] + result[0][1]) % mod

def prefix_fib_sum(n, mod):
    """Compute sum of first n Fibonacci numbers"""
    if n <= 1:
        return 0
    # Formula: sum(f[1]...f[n]) = f[n+2] - 1
    return (fib_index(n + 2, mod) - 1 + mod) % mod


