class SegmentTree:
    def __init__(self, n, mod):
        self.n = n
        self.mod = mod
        self.size = 1
        while self.size < n:
            self.size *= 2
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

    def push(self, p):
        if self.lazy[p] != 0:
            l, r = 2 * p, 2 * p + 1
            self.lazy[l] = (self.lazy[l] + self.lazy[p]) % self.mod
            self.tree[l] = (self.tree[l] + self.lazy[p] * (r - l)) % self.mod
            self.lazy[r] = (self.lazy[r] + self.lazy[p]) % self.mod
            self.tree[r] = (self.tree[r] + self.lazy[p] * (r - l)) % self.mod
