        swapLR = int(first_line_parts[2])
        swapUD = int(first_line_parts[3])
    else:
        swapLR = 0
        swapUD = 0

    # Parse grid (next n lines)
    grid = []
    for i in range(1, n + 1):
        if i < len(parts):
            grid.append(parts[i])

    # Find finish position (convert to 0-indexed)
    finish_pos = None
    dangerous_set = set()
    start_pos = (0, 0)

    for r in range(n):
        if r >= len(grid):
            break
        for c in range(m):
            cell = grid[r][c] if c < len(grid[r]) else ' '
            if cell == 'F':
                finish_pos = (r, c)
            elif cell == '*':
                dangerous_set.add((r, c))

    # Determine actual movement directions based on swaps
    # Original: U=(-1,0), D=(1,0), L=(0,-1), R=(0,1)
    if swapUD:
        move_U = (1, 0)   # U becomes D
        move_D = (-1, 0)  # D becomes U
    else:
        move_U = (-1, 0)
        move_D = (1, 0)

    if swapLR:
        move_L = (0, 1)   # L becomes R
        move_R = (0, -1)  # R becomes L
    else:
        move_L = (0, -1)
        move_R = (0, 1)

    # BFS to find shortest path from start to finish
    queue = [(start_pos, [])]  # (position, path_of_moves)
    visited = {start_pos}
    result_path = []

    while queue:
        (curr_r, curr_c), path = queue.pop(0)

        if (curr_r, curr_c) == finish_pos:
            result_path = path
            break

        # Try all 4 moves
        for move_char, move in [('U', move_U), ('D', move_D), ('L', move_L), ('R', move_R)]:
            (next_r, next_c) = (curr_r + move[0], curr_c + move[1])

            # Check bounds
            if 0 <= next_r < n and 0 <= next_c < m:
                if (next_r, next_c) not in visited and (next_r, next_c) not in dangerous_set:
                    visited.add((next_r, next_c))
                    queue.append(((next_r, next_c), path + [move_char]))

    # Convert path to newline-separated string
    return '\n'.join(result_path) + '\n'
