    available = list(range(1, n + 1))
    moves = []

    def cross_product_mul(x1, y1, x2, y2):
        return x1 * y2 == x2 * y1

    i = 0
    while i < len(available) - 1:
        found = False
        # Try all pairs
        for j in range(i + 1, len(available)):
            idx1, idx2 = available[i], available[j]
            x1, y1 = points[idx1 - 1][0], points[idx1 - 1][2]  # x = a/b, y = c/d
            x2, y2 = points[idx2 - 1][0], points[idx2 - 1][2]

            # Check all 4 move combinations
            for dx1 in [0, 1]:
                for dy1 in [0, 1]:
                    if dx1 + dy1 == 0:  # Must move at least one direction
                        continue
                    for dx2 in [0, 1]:
                        for dy2 in [0, 1]:
                            if dx2 + dy2 == 0:
                                continue

                            nx1 = x1 + dx1
                            ny1 = y1 + dy1
                            nx2 = x2 + dx2
                            ny2 = y2 + dy2

                            if cross_product_mul(nx1, ny1, nx2, ny2):
                                moves.append((idx1, idx2))
                                # Remove these points, but be careful with indices
                                # Replace all occurrences
                                available = [x for x in available if x != idx1 and x != idx2]
                                found = True
                                i = 0  # Restart search
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    break
        i += 1

    result = [str(len(moves))]
    for m in moves:
        result.append(f"{m[0]} {m[1]}")

