    n, m = map(int, lines[0].split())

    # Build adjacency list (1-indexed)
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Parse target values a (0-indexed in array, corresponds to counters 1-n)
    a = list(map(int, lines[m + 1].split()))

    def check(pressed):
        """Check if pressing the given set of buttons wins the dispute."""
        values = [0] * (n + 1)  # values[i] = final value of counter i

        for btn in pressed:
            # Counter btn increases by 1 (being pressed)
            values[btn] += 1
            # All neighbors of btn also increase by 1
            for neighbor in adj[btn]:
                values[neighbor] += 1

        # Check if any counter has target value
        for i in range(1, n + 1):
            if values[i] == a[i - 1]:
                return False
        return True

    # Try pressing no buttons (set())
    if check(set()):
        return "0"

    # Try pressing all buttons
    if check(set(range(1, n + 1))):
        return f"{n}\n" + " ".join(map(str, range(1, n + 1)))

    # For small n, try all possible subsets
    if n <= 20:
        for k in range(1, n):
            for combo in combinations(range(1, n + 1), k):
                if check(set(combo)):
                    result = f"{k}\n" + " ".join(map(str, combo))
