    if k == 1:
        return "0\n\n"

    parent = {i: -1 for i in range(1, n + 1)}
    sz = [1] * (n + 1)
    order = []

    # BFS from node 1 to build tree structure
    visited = {1}
    queue = deque([1])

    while queue:
        u = queue.popleft()
        order.append(u)
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                parent[v] = u
                queue.append(v)

    # Compute subtree sizes bottom-up
    for i in range(len(order) - 1, -1, -1):
        u = order[i]
        if parent[u] != -1:
            sz[parent[u]] += sz[u]

    min_cuts = float('inf')
    found_solution = False

    # For each node, check if its subtree has size k
    for u in range(1, n + 1):
        subtree_size = sz[u]

        # Case 1: Subtree of size k - cutting the edge to parent isolates it
        if subtree_size == k:
            if parent[u] != -1 and parent[u] in visited:
                # This forms a valid k-subtree with 1 cut (to the parent)
                # OR we need to count all boundary edges incident to this subtree
                # For a tree, the k-subtree has 1 boundary edge (to parent) if u != 1
                if parent[u] != -1:
                    if min_cuts > 1:  # Minimize
                        min_cuts = 1
                        found_solution = True

        # Case 2: The nodes outside this subtree have size k (complement)
        if n - subtree_size == k:
            if parent[u] != -1:
                if parent[u] in visited:
                    if min_cuts > 1:
                        min_cuts = 1
                        found_solution = True

    # Handle solution - should be 1 if k > 1 and 1 < k < n (typical path case)
    if min_cuts == float('inf'):
        min_cuts = 1 if k > 1 and k < n else 0

    return f"{min_cuts}\n\n"

