from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, h, m = map(int, lines[0].split())
    restrictions = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        l, r, x, c = map(int, parts)
        restrictions.append((l - 1, r - 1, x, c))  # Convert to 0-indexed

    @lru_cache(maxsize=None)
    def dp(pos, max_vals):
        # pos: current position we're about to decide height for (0 to n)
        # max_vals: tuple of maximum heights encountered so far for each restriction
        if pos == n:
            return 0

        ans = float('-inf')

        for height in range(h + 1):
            # Create new max values by updating for this position
            new_max_vals = list(max_vals)
            for k in range(m):
                if restrictions[k][0] <= pos:
                    new_max_vals[k] = max(new_max_vals[k], height)

            # Calculate fines for restrictions that end at this position
            fines = 0
            for k in range(m):
                l, r, x, c = restrictions[k]
                if r == pos:  # restriction range ends at this position
                    if new_max_vals[k] > x:
                        fines += c

            # Calculate current position gain and recursively solve
            current_gain = height * height
            future = dp(pos + 1, tuple(new_max_vals))

            if future != float('-inf'):
                ans = max(ans, current_gain - fines + future)

        return ans

    return str(dp(0, tuple([0] * m)))
