def solve_maze(grid):
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    results = []
    from collections import deque
    dq = deque([(0, 0, [[1]] if grid[0][0] == 1 else [[0]]))
    while dq:
        (r, c, path) = dq.popleft()
        if r == h - 1 and c == w - 1:
            results.append(path)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != '#':
                dq.append((nr, nc, path + [(nr, nc)]))
    return results
