        return False
    if len(pieces) == 1:
        return True

    expected = 2
    remainder = False

    for i in range(1, len(pieces)):
        p = pieces[i]
        if p == expected:
            expected *= 2
        elif not remainder and p < expected and p > 0:
            remainder = True
        elif p < expected:
            continue
        else:
            return False

    return True
